import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        num_groups = int(next(iterator))
    except StopIteration:
        return

    for _ in range(num_groups):
        try:
            num_friends = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(num_friends + 1)]

        for i in range(1, num_friends + 1):
            line_parts = []
            while True:
                try:
                    token = next(iterator)
                    line_parts.append(token)
                except StopIteration:
                    break
                if len(line_parts) > 0:
                    pass

            if not line_parts:
                continue

            friends_list = [int(x) for x in line_parts]
            adj[i] = friends_list

        def bfs(start_node, n_nodes, graph):
            dist = [-1] * (n_nodes + 1)
            dist[start_node] = 0
            queue = deque([start_node])

            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        queue.append(v)
            return dist[1:]

        notoriety = {}

        for i in range(1, num_friends + 1 + 1):
            if i > num_friends:
                break
            distances = bfs(i, num_friends, adj)
            total_dist = sum(distances)
            avg_dist = total_dist / num_friends
            notoriety[i] = avg_dist

        best_friend = -1
        min_notoriety = float('inf')

        for i in range(1, num_friends + 1, 1):
            if notoriety[i] < min_notoriety:
                min_notoriety = notoriety[i]
                best_friend = i
            elif notoriety[i] == min_notoriety:
                if i < best_friend:
                    best_friend = i

        print(f"{best_friend} {min_notoriety:.6f}")

if __name__ == "__main__":
    solve()
